def find_y_robust(N, D_over_L, max_iter=10000):
    y = np.zeros(N)
    for n in range(1, N):
        # y[n] must be in [0, 1] and |y[n] - y[m]| >= D_over_L / (m+1 + n+1)
        # We can find the available intervals in [0, 1].
        forbidden = []
        for m in range(n):
            forbidden.append((y[m] - D_over_L / (m+1 + n+1), y[m] + D_over_L / (m+1 + n+1)))

        # Merge forbidden intervals
        forbidden.sort()
        merged = []
        if forbidden:
            curr_start, curr_end = forbidden[0]
            for i in range(1, len(forbidden)):
                s, e = forbidden[i]
                if s < curr_end:
                    curr_end = max(curr_end, e)
                else:
                    merged.append((curr_start, curr_end))
                    curr_start, curr_end = s, e
            merged.append((curr_start, curr_end))

        # Find an available interval in [0, 1]
        available = []
        last_end = 0
        for s, e in merged:
            if s > last_end:
                available.append((last_end, s))
            last_end = max(last_end, e)
        if last_end < 1:
            available.append((last_end, 1))

        if not available:
            return None

        # Pick the midpoint of the largest available interval
        best_interval = max(available, key=lambda x: x[1] - x[0])
        y[n] = (best_interval[0] + best_interval[1]) / 2
    return y

